package ro.boardgamecafe.core.api.billing.dto;

import java.math.BigDecimal;
import java.util.UUID;
import jakarta.validation.constraints.*;

/** Request bodies for persons, checkout and payment. */
public final class BillingRequests {
    private BillingRequests() {
    }

    public record SetPersons(@NotNull @Min(1) @Max(100) Integer persons) {}

    /**
     * idempotencyKey: a new UUID generated by the client for each payment attempt and reused only when
     * retrying that same attempt (for example after a timeout).
     * expectedTotal: optional; if present and different from the server total, the payment is refused (409).
     * simulateFailure: demo switch for the FAILED path of the simulated payment.
     */
    public record Pay(@NotNull UUID idempotencyKey, @DecimalMin("0.00") BigDecimal expectedTotal,
            Boolean simulateFailure) {}
}
